using System;using System.IO;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.Drawing;using V15Voice;
public static class CommunityVoiceUiTests {
 static int n;static object F(object f,string name){return f.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(f);}static object C(object f,string name,params object[] args){return f.GetType().GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(f,args);}static void Check(bool b,string s){if(!b)throw new Exception(s);Console.WriteLine("PASS "+s);n++;}static System.Collections.Generic.IEnumerable<Control> Walk(Control c){foreach(Control x in c.Controls){yield return x;foreach(var y in Walk(x))yield return y;}}
 [STAThread]public static void Main(){Application.EnableVisualStyles();var f=new MainForm();f.Show();Application.DoEvents();var cat=(VoiceCatalog)F(f,"catalog");var family=(ComboBox)F(f,"family");var language=(ComboBox)F(f,"languagePicker");Check(family.Items.Count==8&&family.Items[7].ToString().Contains("RVC"),"RVC gets separate source selector while existing group indices remain stable");Check(!cat.All.Any(p=>p.Key=="C:sarah_atlas"),"Rejected Sarah cannot be selected in Studio or A/B");C(f,"SelectVoice","C:adam_rvc");Check(family.SelectedIndex==7&&language.SelectedIndex==0,"Adam selection remains in English mode");Check((string)C(f,"Key")=="C:adam_rvc","Studio selects community Adam, distinct from existing Kokoro Adam");Check(((Label)F(f,"voiceInfo")).Text.Contains("Kể chuyện"),"Voice panel shows suggested content style");var settings=(VoiceSettings)C(f,"CaptureSettings");Check(settings.Key=="C:adam_rvc","Shared Studio/queue settings retain selected community voice");Check(Walk(f).OfType<Button>().Any(b=>b.Text.Contains("giọng cộng đồng")),"Tools provides community source/status dialog");Check(Walk(f).OfType<Button>().Any(b=>b.Text.Contains("nguồn & trạng thái")),"Library provides community source/status dialog");C(f,"SetBusy",true);C(f,"ShowCommunityVoices");Check(Application.OpenForms.Count==1,"Community chooser cannot change voice during active work");C(f,"SetBusy",false);
  var timer=new Timer{Interval=250};bool saw=false;timer.Tick+=(s,e)=>{foreach(Form d in Application.OpenForms){if(d==f)continue;saw=true;var text=Walk(d).OfType<TextBox>().Select(t=>t.Text).FirstOrDefault()??"";Check(text.Contains("SARAH ATLAS")&&text.Contains("CHƯA ĐƯA"),"Dialog discloses rejected model rather than advertising it as ready");Check(text.Contains("index chạy CPU")||text.Contains("RVC"),"Dialog explains offline conversion workflow");var b=Walk(d).OfType<Button>().First(x=>x.Text=="Dùng Adam RVC");b.PerformClick();break;}timer.Stop();};timer.Start();C(f,"ShowCommunityVoices");Check(saw&&family.SelectedIndex==7,"One-click use action returns to Studio with Adam selected");f.Size=new Size(1100,740);Application.DoEvents();Check(((TabControl)F(f,"tabs")).TabCount==7,"No extra video workflow or main tab added");using(var bm=new Bitmap(f.Width,f.Height)){using(var g=Graphics.FromImage(bm))g.CopyFromScreen(f.Location,Point.Empty,f.Size);bm.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"validation/community210-ui.png"));}f.Close();Console.WriteLine("TOTAL COMMUNITY UI "+n+" passed.");
 }
}
